  void sse_encode_vault_status_dto(
    VaultStatusDto self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_bool(self.initialized, serializer);
    sse_encode_bool(self.unlocked, serializer);
    sse_encode_String(self.dbPath, serializer);
  }
}
